1	import React, { useLayoutEffect, useRef } from 'react';
2	import styles from './LiquidGlassMorph.module.scss';
3	
4	/**
5	 * Forme de verre animée : un unique élément en `backdrop-filter` (même verre que les panneaux,
6	 * cf. .fusionMenuContainer) dont la silhouette est redessinée à chaque image via `clip-path:
7	 * path(...)`. Le flou du fond reste ainsi un vrai flou CSS pendant tout le morphing — aucun
8	 * filtre SVG n'est appliqué au verre ni à un de ses ancêtres (un `filter`, une `opacity` < 1 ou un
9	 * `clip-path` sur un ancêtre isolerait le `backdrop-filter` du fond et le rendrait opaque).
10	 *
11	 * L'ombre portée est un calque séparé (frère, jamais ancêtre du verre) : la forme noircie, floutée
12	 * puis découpée à l'EXTÉRIEUR de la silhouette, exactement comme un `box-shadow` qui ne se dessine
13	 * jamais sous l'élément — sans quoi le verre, translucide, paraîtrait plus sombre que les vrais
14	 * panneaux au moment où ceux-ci prennent le relais.
15	 *
16	 * Les positions sont en px, en `position: fixed` ; `pathAt(t, dx, dy)` décrit la forme dans le
17	 * repère de la boîte (left, top), décalée de (dx, dy).
18	 */
19	
20	export interface LiquidGlassMorphTimingProps {
21	  /** Durée totale en ms. */
22	  duration: number;
23	  pathAt: (t: number, dx: number, dy: number) => string;
24	  /** Joue la timeline de t = 1 vers t = 0 (fusion plutôt que division, par exemple). */
25	  reverse?: boolean;
26	  onDone?: () => void;
27	}
28	
29	interface LiquidGlassMorphProps extends LiquidGlassMorphTimingProps {
30	  left: number;
31	  top: number;
32	  width: number;
33	  height: number;
34	}
35	
36	// Marge du calque d'ombre autour de la boîte, pour que le flou ne soit pas rogné.
37	const SHADOW_MARGIN = 64;
38	
39	/**
40	 * Ombre portée animée seule (calque séparé, cf. le commentaire de tête) : réutilisée telle quelle
41	 * quand la silhouette de verre elle-même est portée par un élément réel plutôt que par `.glass`
42	 * (cf. `useLiquidGlassClip`) — un vrai panneau (`backdrop-filter` + `background`) n'a pas cette
43	 * ombre en evenodd qui épouse sa silhouette pendant qu'elle change de forme.
44	 *
45	 * Composant purement passif : pas de boucle RAF à elle (`ref` exposée via `shadowRef`, à piloter
46	 * depuis `applyLiquidGlassShadow` — cf. plus bas). Une boucle RAF indépendante de celle qui anime
47	 * l'élément réel (`useLiquidGlassClip`) dériverait de quelques millisecondes d'une frame à l'autre
48	 * (deux `performance.now()` capturés séparément) : à un instant donné, l'ombre dessinerait une
49	 * forme légèrement en avance ou en retard sur le panneau réel — les deux contours, décalés,
50	 * deviendraient tous les deux visibles un court instant, comme deux silhouettes superposées.
51	 */
52	export const LiquidGlassShadow: React.FC<
53	  Omit<LiquidGlassMorphProps, 'duration' | 'pathAt' | 'reverse' | 'onDone'> & { shadowRef: React.RefObject<LiquidGlassShadowHandle | null> }
54	> = ({ left, top, width, height, shadowRef }) => {
55	  const shadowShapeRef = useRef<HTMLDivElement>(null);
56	  const shadowClipRef = useRef<HTMLDivElement>(null);
57	
