1	import { useEffect, useRef, useState } from 'react';
2	import { showError, showSuccess, showWarning } from '@/utils/toast';
3	import { parseGCode, stateAt, SUSPICIOUS_C_RANGE_DEG, type ParsedGCode } from '@/components/gcodeLayer';
4	
5	/**
6	 * Logique de l'espace Prévisualisation, sans interface : chargement de fichier G-code (dépôt sur
7	 * la fenêtre ou sélecteur), horloge de lecture et affichage des trajets à vide. Le rendu 3D est
8	 * fait par Viewport3D, piloté par les événements :
9	 *  - `apex-gcode-loaded` { parsed } : nouvelle trajectoire à afficher ;
10	 *  - `apex-gcode-time` { t } : position de lecture (index de mouvement fractionnaire) ;
11	 *  - `apex-gcode-show-travel` { show } : affichage des trajets à vide.
12	 */
13	
14	export const GCODE_SPEED_OPTIONS = [25, 100, 400, 1600, 6400]; // mouvements par seconde
15	export const GCODE_ACCEPT = '.gcode,.gco,.g,.ngc';
16	const ACCEPTED_EXT = /\.(gcode|gco|g|ngc)$/i;
17	
18	export interface GCodeFileInfo {
19	  name: string;
20	  moves: number;
21	  extruding: number;
22	  minZ: number;
23	  maxZ: number;
24	  minC: number;
25	  maxC: number;
26	}
27	
28	const dispatchTime = (t: number) =>
29	  window.dispatchEvent(new CustomEvent('apex-gcode-time', { detail: { t } }));
30	
31	/** @param active Espace Prévisualisation affiché (active le dépôt de fichier, coupe la lecture sinon). */
32	export function useGCodePreview(active: boolean) {
33	  const parsedRef = useRef<ParsedGCode | null>(null);
34	  const tRef = useRef(0);
35	  const dragDepthRef = useRef(0);
36	
37	  const [fileInfo, setFileInfo] = useState<GCodeFileInfo | null>(null);
38	  const [t, setT] = useState(0);
39	  const [isPlaying, setIsPlaying] = useState(false);
40	  const [speed, setSpeed] = useState(GCODE_SPEED_OPTIONS[1]);
41	  const [showTravel, setShowTravel] = useState(false);
42	  const [isDragging, setIsDragging] = useState(false);
43	  // Le temps de lire le fichier et de parser son texte (`loadFile`, ci-dessous) : permet à
44	  // GCodePreviewBar de s'afficher dès le début du chargement plutôt que d'attendre `fileInfo`.
45	  const [isLoading, setIsLoading] = useState(false);
46	
47	  useEffect(() => {
48	    if (!active) setIsPlaying(false);
49	  }, [active]);
50	
51	  useEffect(() => {
52	    window.dispatchEvent(new CustomEvent('apex-gcode-show-travel', { detail: { show: showTravel } }));
53	  }, [showTravel]);
54	
55	  // Horloge de lecture : avance `t` à `speed` mouvements/s, pousse chaque image au viewport et
56	  // rafraîchit l'état React à ~20 Hz seulement.
57	  useEffect(() => {
58	    if (!isPlaying) return;
59	    const parsed = parsedRef.current;
60	    if (!parsed) return;
61	    const last = parsed.moves.length - 1;
62	    let raf = 0;
63	    let prev = performance.now();
64	    let sinceUiSync = 0;
65	    const step = (now: number) => {
66	      const dt = (now - prev) / 1000;
67	      prev = now;
68	      tRef.current = Math.min(last, tRef.current + speed * dt);
69	      dispatchTime(tRef.current);
70	      sinceUiSync += dt;
71	      if (tRef.current >= last) {
72	        setT(last);
73	        setIsPlaying(false);
74	        return;
75	      }
76	      if (sinceUiSync > 1 / 20) {
77	        sinceUiSync = 0;
78	        setT(tRef.current);
79	      }
80	      raf = requestAnimationFrame(step);
81	    };
82	    raf = requestAnimationFrame(step);
83	    return () => cancelAnimationFrame(raf);
84	  }, [isPlaying, speed]);
85	
86	  const loadFile = async (file: File) => {
87	    if (!ACCEPTED_EXT.test(file.name)) {
88	      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
89	      return;
90	    }
91	    setIsLoading(true);
92	    let parsed: ParsedGCode;
93	    try {
94	      parsed = parseGCode(await file.text());
95	    } catch {
96	      showError('Impossible de lire ce fichier G-code.');
97	      setIsLoading(false);
98	      return;
99	    }
100	    if (parsed.moves.length < 2) {
101	      showError('Aucune trajectoire G00 exploitable dans ce fichier.');
102	      setIsLoading(false);
103	      return;
104	    }
105	
106	    parsedRef.current = parsed;
107	    const last = parsed.moves.length - 1;
108	    tRef.current = last;
109	    setIsPlaying(false);
110	    setT(last);
111	    window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));
112	
113	    setFileInfo({
114	      name: file.name,
115	      moves: parsed.moves.length,
116	      extruding: parsed.extrudingCount,
117	      minZ: parsed.minZ,
118	      maxZ: parsed.maxZ,
119	      minC: parsed.minC,
120	      maxC: parsed.maxC,
121	    });
122	    setIsLoading(false);
123	
124	    if (parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
125	      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
126	    } else {
127	      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
128	    }
129	  };
130	
131	  /** Ouvre le sélecteur de fichier système (sans élément `<input>` dans l'interface). */
132	  const openFilePicker = () => {
133	    const input = document.createElement('input');
134	    input.type = 'file';
135	    input.accept = GCODE_ACCEPT;
136	    input.onchange = () => {
137	      const file = input.files?.[0];
138	      if (file) loadFile(file);
139	    };
140	    input.click();
141	  };
142	
143	  // Dépôt de fichier sur toute la fenêtre tant que l'espace est affiché : le viewport garde la
144	  // souris pour la caméra, aucun élément d'interface n'a donc besoin de capter le dépôt.
145	  useEffect(() => {
146	    if (!active) return;
147	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
148	    const onDragEnter = (e: DragEvent) => {
149	      if (!hasFiles(e)) return;
150	      e.preventDefault();
151	      dragDepthRef.current++;
152	      setIsDragging(true);
153	    };
154	    const onDragOver = (e: DragEvent) => {
155	      if (!hasFiles(e)) return;
156	      e.preventDefault();
157	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
158	    };
159	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
160	    const onDragLeave = (e: DragEvent) => {
161	      if (!hasFiles(e)) return;
162	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
163	      if (dragDepthRef.current === 0) setIsDragging(false);
164	    };
165	    const onDrop = (e: DragEvent) => {
166	      if (!hasFiles(e)) return;
167	      e.preventDefault();
168	      dragDepthRef.current = 0;
169	      setIsDragging(false);
170	      const file = e.dataTransfer?.files?.[0];
171	      if (file) loadFile(file);
172	    };
173	    window.addEventListener('dragenter', onDragEnter);
174	    window.addEventListener('dragover', onDragOver);
175	    window.addEventListener('dragleave', onDragLeave);
176	    window.addEventListener('drop', onDrop);
177	    return () => {
178	      window.removeEventListener('dragenter', onDragEnter);
179	      window.removeEventListener('dragover', onDragOver);
180	      window.removeEventListener('dragleave', onDragLeave);
181	      window.removeEventListener('drop', onDrop);
182	      dragDepthRef.current = 0;
183	      setIsDragging(false);
184	    };
185	  }, [active]);
186	
187	  /** Place la lecture sur l'index de mouvement `value` (fractionnaire) et met la lecture en pause. */
188	  const seek = (value: number) => {
189	    setIsPlaying(false);
190	    tRef.current = value;
191	    setT(value);
192	    dispatchTime(value);
193	  };
194	
195	  /** Lecture/pause ; repart du début si la lecture est au bout. */
196	  const togglePlay = () => {
197	    const parsed = parsedRef.current;
198	    if (!parsed) return;
199	    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
200	    setIsPlaying(!isPlaying);
201	  };
202	
203	  const parsed = parsedRef.current;
204	  /** État machine interpolé (r, c, z, b) à la position de lecture. */
205	  const current = parsed ? stateAt(parsed.moves, t) : null;
206	  /** Mouvement en cours d'exécution (pour savoir s'il extrude). */
207	  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
208	  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;
209	
210	  return {
211	    fileInfo,
212	    t,
213	    lastIndex,
214	    current,
215	    currentMove,
216	    isPlaying,
217	    togglePlay,
218	    seek,
219	    speed,
220	    setSpeed,
221	    showTravel,
222	    setShowTravel,
223	    isDragging,
224	    isLoading,
225	    loadFile,
226	    openFilePicker,
227	  };
228	}
