import { parseGCode, stateAt, SUSPICIOUS_C_RANGE_DEG, type ParsedGCode } from '@/components/gcodeLayer';

/**
 * Logique de l'espace Prévisualisation, sans interface : chargement de fichier G-code (dépôt sur
