import * as BABYLON from 'babylonjs';
import 'babylonjs-loaders';
import headModelUrl from '@/assets/models/aetheris-4.glb?url';

/**
 * G-code polaire 4 axes de l'Apex : parseur + calque Babylon de prévisualisation.
 *
 * Ce n'est PAS un G-code cartésien de slicer classique : une seule commande de déplacement,
 * `G00 Y<C> X<R> Z<Z> B<B> [E<e>] F<f>`.
 *  - X = R : rayon depuis le centre du plateau (mm, ≥ 0).
 *  - Y = C : angle du plateau (degrés, absolu, JAMAIS replié modulo 360 — le générateur garde
 *    la continuité angulaire, un C > 360 ou négatif est normal).
 *  - Z : hauteur (mm). B : inclinaison de la tête vers +R (à l'opposé de l'axe de rotation), en
 *    degrés.
 *  - E (optionnel) : position absolue de l'extrudeur. E croissant = dépôt ; E absent ou
 *    stationnaire = trajet à vide.
 *
 * Représentation (cf. `createGCodeLayer`) :
 *  - La matière est stockée une fois pour toutes en repère plateau (x = R cos C, z = R sin C,
 *    avec le C du moment du dépôt) sous un noeud dont la rotation suit le C courant : plateau
 *    et matière tournent strictement ensemble.
 *  - La matière est un cordon (tube à section elliptique, cf. `buildBeadMesh`) orienté selon
 *    l'axe de buse du moment du dépôt ; les trajets à vide restent de simples lignes.
 *  - La tête reste dans le demi-plan machine fixe (R, 0, Z) ; c'est le plateau qui tourne pour
 *    amener la pièce sous elle.
 *  - R/Z sont les positions machine du PIVOT de l'axe B, pas de la buse : la pointe de buse est
 *    à NOZZLE_PIVOT_MM sous le pivot, le long de l'axe de la tête (cf. `nozzleTip`). Tête et
 *    matière déposée sont affichées à la pointe de buse ; l'état machine exposé (`stateAt`)
 *    reste en coordonnées pivot.
 *  - Tout est interpolé dans l'espace (R, C, Z, B) du firmware, jamais en cartésien : les
 *    segments sont subdivisés en angle pour suivre l'arc réellement parcouru, et la position
 *    animée entre deux consignes est interpolée en (R, C, Z, B) puis convertie.
 *  - Aucune décimation "1 point sur N" (sauts angulaires visibles sur les portions courbes).
 */

export interface GCodeMove {
  r: number;
  c: number;
  z: number;
  b: number;
  extruding: boolean;
}

export interface ParsedGCode {
  moves: GCodeMove[];
  minZ: number;
  maxZ: number;
  maxR: number;
  minC: number;
  maxC: number;
  extrudingCount: number;
}

const DEG2RAD = Math.PI / 180;
// Pas angulaire max d'un sous-segment : au-delà, la corde cartésienne s'écarte visiblement de
// l'arc réellement décrit par le firmware (qui interpole en C, pas en x/y).
const MAX_SUBSEGMENT_DEG = 0.5;
/** Au-delà de cette amplitude totale de C, le fichier vient très probablement de la version
 * boguée du générateur (C qui dérive de tour en tour au lieu d'osciller dans une plage étroite). */
export const SUSPICIOUS_C_RANGE_DEG = 720;

/** Distance entre la pointe de buse et le pivot de l'axe B (mm), le long de l'axe de la tête. */
export const NOZZLE_PIVOT_MM = 46;

/**
 * Pointe de buse (rayon, hauteur) dans le demi-plan machine, depuis la position du pivot (R, Z)
 * et l'inclinaison B (radians). La tête penche vers +R (cf. `headDir` dans `apply`), donc la
 * buse, SOUS le pivot, part vers −R. Z est calé pour que tête droite (B = 0) la buse soit
 * exactement à Z : seul l'écart dû à l'inclinaison, L·(1 − cos B), s'ajoute en hauteur.
 */
function nozzleTip(r: number, z: number, bRad: number, out: { r: number; z: number }) {
  out.r = r - NOZZLE_PIVOT_MM * Math.sin(bRad);
  out.z = z + NOZZLE_PIVOT_MM * (1 - Math.cos(bRad));
  return out;
}

const G00_RE = /^G0*0(?![0-9])/i;
const WORD_RE = /([XYZBEF])\s*([-+]?(?:\d+\.?\d*|\.\d+))/gi;

export function parseGCode(text: string): ParsedGCode {
  const moves: GCodeMove[] = [];
  let r = 0, c = 0, z = 0, b = 0;
  let lastE: number | null = null;
  let extrudingCount = 0;

  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.replace(/\(.*?\)/g, '').replace(/;.*$/, '').trim();
    if (!line || !G00_RE.test(line)) continue;

    let e: number | null = null;
    WORD_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = WORD_RE.exec(line)) !== null) {
      const value = parseFloat(m[2]);
      if (Number.isNaN(value)) continue;
      switch (m[1].toUpperCase()) {
        case 'X': r = value; break;
        case 'Y': c = value; break;
        case 'Z': z = value; break;
        case 'B': b = value; break;
        case 'E': e = value; break;
      }
    }

    const extruding = e !== null && lastE !== null && e > lastE + 1e-9;
    if (e !== null) lastE = e;
    if (extruding) extrudingCount++;
    moves.push({ r, c, z, b, extruding });
  }

  // Bornes en Z/R de la pointe de buse (ce qui est affiché), pas du pivot.
  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
  const tip = { r: 0, z: 0 };
  for (const mv of moves) {
    nozzleTip(mv.r, mv.z, mv.b * DEG2RAD, tip);
    if (tip.z < minZ) minZ = tip.z;
    if (tip.z > maxZ) maxZ = tip.z;
    if (Math.abs(tip.r) > maxR) maxR = Math.abs(tip.r);
    if (mv.c < minC) minC = mv.c;
    if (mv.c > maxC) maxC = mv.c;
  }
  if (!moves.length) { minZ = maxZ = minC = maxC = 0; }

  return { moves, minZ, maxZ, maxR, minC, maxC, extrudingCount };
}

/** Position (R, C, Z, B) interpolée linéairement — comme le firmware — au temps `t` exprimé
 * en index de mouvement fractionnaire. */
export function stateAt(moves: GCodeMove[], t: number) {
  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
  const a = moves[i];
  const b = moves[Math.min(moves.length - 1, i + 1)];
  const f = Math.max(0, Math.min(1, t - i));
  return {
    r: a.r + (b.r - a.r) * f,
    c: a.c + (b.c - a.c) * f,
    z: a.z + (b.z - a.z) * f,
    b: a.b + (b.b - a.b) * f,
  };
}

