let parsed: ParsedGCode | null = null;
let segments = new Uint32Array(0);
let extruded: PathMesh | null = null;
let travel: PathMesh | null = null;
let time = 0;
let showTravel = false;
let fullHead = true;

// Troncature de la tête : un plan de coupe (repère MONDE, cf. Material.clipPlane) posé à
// HEAD_CLIP_HEIGHT_MM au-dessus de la pointe de buse, normale vers le bas — tout ce qui est
// au-dessus disparaît, ne laissant voir que la buse. Recalculé à chaque `apply()` puisque
// `headNode` bouge et s'incline (headDir) avec la position/B courants. Un seul plan, partagé par
// tous les matériaux de la tête (primitives de repli + modèle glTF, potentiellement plusieurs
// matériaux) : `material.clipPlane` prend l'objet lui-même, jamais recréé, pour éviter une
// allocation par frame.
const headClipPlane = new BABYLON.Plane(0, -1, 0, 0);
const headClipMaterials = new Set<BABYLON.Material>();
const registerHeadMaterial = (mat: BABYLON.Material | null | undefined) => {
  if (!mat || headClipMaterials.has(mat)) return;
  headClipMaterials.add(mat);
  mat.clipPlane = fullHead ? null : headClipPlane;
};
const updateHeadClipPlane = () => {
  // headDir (mis à jour par `apply`, cf. plus bas) est la direction +Y locale de headNode en
  // repère monde : le plan de coupe reste perpendiculaire à l'axe de la tête, comme une buse
  // sciée à hauteur constante le long de cet axe plutôt qu'à Z monde constant (qui découperait
  // de travers dès que B ≠ 0).
  const origin = headNode.position;
  const point = origin.add(headDir.scale(HEAD_CLIP_HEIGHT_MM));
  BABYLON.Plane.FromPositionAndNormalToRef(point, headDir.scale(-1), headClipPlane);
};

const up = BABYLON.Vector3.Up();
const headDir = new BABYLON.Vector3();
const headTip = { r: 0, z: 0 };

