// transparent au repos, léger fond blanc au survol, cyan pour l'option active.
.root {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.sliderRow {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 26px;
}

