// Case à cocher « Afficher la tête d'outil complète », posée juste au-dessus du curseur de
// vitesse — même famille de libellé (11px, 600) que .label ci-dessous.
.checkboxRow {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 20px;
  font-size: 11px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.7);
  cursor: pointer;
  user-select: none;

  &:hover {
    color: rgba(255, 255, 255, 0.95);
  }
}

.checkbox {
  appearance: none;
  flex: 0 0 auto;
  width: 14px;
  height: 14px;
  margin: 0;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.05);
  cursor: pointer;
  position: relative;
  transition: all 0.15s ease;

  &:hover {
    border-color: rgba(255, 255, 255, 0.5);
  }

  &:checked {
    background: rgba(0, 240, 255, 0.18);
    border-color: #00f0ff;
    box-shadow: 0 0 8px rgba(0, 240, 255, 0.25);

    &::after {
      content: '';
      position: absolute;
      left: 4px;
      top: 1px;
      width: 4px;
      height: 8px;
      border: solid #00f0ff;
      border-width: 0 2px 2px 0;
      transform: rotate(45deg);
    }
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.sliderRow {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 26px;
}

