// Repère tournant du plateau : toute la matière déposée en est enfant.
const plateNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Plate`, scene);
plateNode.parent = root;

// Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le noeud
// est ensuite orienté pour que ce corps penche de B vers +R. Primitives provisoires, remplacées
// par le vrai modèle (loadHeadModel) une fois chargé ; gardées en repli s'il échoue.
const headNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Head`, scene);
headNode.parent = root;
headNode.rotationQuaternion = BABYLON.Quaternion.Identity();

// Troncature de la tête : un plan de coupe (repère MONDE, cf. Material.clipPlane) posé à
// HEAD_CLIP_HEIGHT_MM au-dessus de la pointe de buse, normale vers le bas — tout ce qui est
// au-dessus disparaît, ne laissant voir que la buse. Recalculé à chaque `apply()` puisque
// `headNode` bouge et s'incline avec la position/B courants. Un seul plan, partagé par tous les
// matériaux de la tête (primitives de repli + modèle glTF, potentiellement plusieurs matériaux) :
// `material.clipPlane` prend l'objet lui-même, jamais recréé, pour éviter une allocation par frame.
const headClipPlane = new BABYLON.Plane(0, -1, 0, 0);
const headClipMaterials = new Set<BABYLON.Material>();
let fullHead = true;
const registerHeadMaterial = (mat: BABYLON.Material | null | undefined) => {
  if (!mat || headClipMaterials.has(mat)) return;
  headClipMaterials.add(mat);
  mat.clipPlane = fullHead ? null : headClipPlane;
};

const nozzleMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}NozzleMat`, scene);
nozzleMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
nozzle.position.y = 4.5;
nozzle.material = nozzleMat;
nozzle.parent = headNode;
const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
bodyMat.alpha = 0.55;
const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
body.position.y = 9 + 13;
body.material = bodyMat;
body.parent = headNode;
nozzle.isPickable = false;
body.isPickable = false;
headNode.setEnabled(false);
registerHeadMaterial(nozzleMat);
registerHeadMaterial(bodyMat);

let disposed = false;
loadHeadModel(scene, headNode, () => disposed)
  .then((loaded) => {
    if (!loaded) return;
    nozzle.dispose(false, true);
    body.dispose(false, true);
    // Modèle glTF : potentiellement plusieurs matériaux (un par sous-maillage), tous soumis au
    // même plan de coupe que les primitives qu'ils remplacent.
    for (const mesh of headNode.getChildMeshes()) registerHeadMaterial(mesh.material);
  })
  .catch((err) => console.warn('Modèle de tête G-code non chargé, primitives conservées :', err));

// Cordon : teinte portée par les couleurs de sommets (dégradé en hauteur), le matériau n'apporte
// que l'éclairage. Faces arrière dessinées pour ne pas dépendre du sens des triangles, les
// normales explicites (vers l'extérieur) donnant l'éclairage.
const beadMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}BeadMat`, scene);
beadMat.diffuseColor = new BABYLON.Color3(1, 1, 1);
beadMat.specularColor = new BABYLON.Color3(0.25, 0.25, 0.25);
beadMat.specularPower = 48;
beadMat.emissiveColor = new BABYLON.Color3(0.08, 0.1, 0.14);
beadMat.backFaceCulling = false;

let parsed: ParsedGCode | null = null;
let segments = new Uint32Array(0);
let extruded: PathMesh | null = null;
let travel: PathMesh | null = null;
let time = 0;
let showTravel = false;

// `Material.clipPlane` est en repère MONDE — `headNode.position`/`headDir` (ci-dessous) sont eux
// en repère local (parent = root, potentiellement lui-même tourné/positionné dans la scène) : il
// faut donc repasser par la matrice monde de headNode, forcée à jour après avoir posé sa
// position/rotation dans `apply()`.
const worldOrigin = new BABYLON.Vector3();
const worldUp = new BABYLON.Vector3();
const worldClipPoint = new BABYLON.Vector3();
const updateHeadClipPlane = () => {
  headNode.computeWorldMatrix(true);
  // Origine monde de la tête (pointe de buse) et direction +Y locale (axe de la tête) en monde :
  // le plan de coupe reste perpendiculaire à l'axe de la tête, comme une buse sciée à hauteur
  // constante le long de cet axe plutôt qu'à Y monde constant (qui découperait de travers dès
  // que B ≠ 0 ou que le plateau/la tête est incliné dans la scène).
  BABYLON.Vector3.TransformCoordinatesToRef(BABYLON.Vector3.ZeroReadOnly, headNode.getWorldMatrix(), worldOrigin);
  BABYLON.Vector3.TransformNormalToRef(up, headNode.getWorldMatrix(), worldUp);
  worldUp.normalize();
  worldOrigin.addToRef(worldUp.scale(HEAD_CLIP_HEIGHT_MM), worldClipPoint);
  // `clipPlane` masque le demi-espace où (normal · p + d) > 0 : la normale doit donc pointer vers
  // le côté à MASQUER, ici le corps au-dessus de la coupe — pas vers le côté conservé (buse,
  // en dessous). D'où +worldUp (vers le haut), pas -worldUp.
  BABYLON.Plane.FromPositionAndNormalToRef(worldClipPoint, worldUp, headClipPlane);
};

const up = BABYLON.Vector3.Up();
const headDir = new BABYLON.Vector3();

