const fs = require('fs');
const data = fs.readFileSync('src/assets/models/aetheris-4.glb');
const length = data.readUInt32LE(8);
let offset = 12;
let gltf, bin;
while (offset < length) {
  const chunkLen = data.readUInt32LE(offset);
  const chunkType = data.readUInt32LE(offset+4);
  const chunkData = data.slice(offset+8, offset+8+chunkLen);
  if (chunkType === 0x4E4F534A) gltf = JSON.parse(chunkData.toString('utf8'));
  else bin = chunkData;
  offset += 8 + chunkLen;
}
function getAccessor(idx) {
  const acc = gltf.accessors[idx];
  const bv = gltf.bufferViews[acc.bufferView];
  const compSize = {5126:4}[acc.componentType];
  const numComp = {SCALAR:1,VEC2:2,VEC3:3,VEC4:4}[acc.type];
  const start = (bv.byteOffset||0) + (acc.byteOffset||0);
  const out = [];
  for (let i=0;i<acc.count;i++) {
    const o = start + i*numComp*compSize;
    const v=[];
    for (let c=0;c<numComp;c++) v.push(bin.readFloatLE(o+c*compSize));
    out.push(v);
  }
  return out;
}
gltf.meshes.forEach((m,i)=>{
  if (!/NOZZLE|Bloc de chauffe/i.test(m.name)) return;
  console.log('MESH', i, m.name);
  m.primitives.forEach((p,pi)=>{
    const posAcc = p.attributes.POSITION;
    const pos = getAccessor(posAcc);
    let min=[Infinity,Infinity,Infinity], max=[-Infinity,-Infinity,-Infinity];
    for (const v of pos) for(let k=0;k<3;k++){ if(v[k]<min[k])min[k]=v[k]; if(v[k]>max[k])max[k]=v[k]; }
    console.log(' prim',pi,'verts',pos.length,'min',min,'max',max,'material',gltf.materials[p.material]?.name);
  });
});
"

