const fs = require('fs');
const data = fs.readFileSync('src/assets/models/aetheris-4.glb');
const length = data.readUInt32LE(8);
let offset = 12;
let gltf, bin;
while (offset < length) {
  const chunkLen = data.readUInt32LE(offset);
  const chunkType = data.readUInt32LE(offset+4);
  const chunkData = data.slice(offset+8, offset+8+chunkLen);
  if (chunkType === 0x4E4F534A) gltf = JSON.parse(chunkData.toString('utf8'));
  else bin = chunkData;
  offset += 8 + chunkLen;
}
function getAccessor(idx) {
  const acc = gltf.accessors[idx];
  const bv = gltf.bufferViews[acc.bufferView];
  const compSize = {5126:4,5123:2,5125:4}[acc.componentType];
  const numComp = {SCALAR:1,VEC2:2,VEC3:3,VEC4:4}[acc.type];
  const start = (bv.byteOffset||0) + (acc.byteOffset||0);
  const out = [];
  for (let i=0;i<acc.count;i++) {
    const o = start + i*numComp*compSize;
    const v=[];
    for (let c=0;c<numComp;c++) {
      if (acc.componentType===5126) v.push(bin.readFloatLE(o+c*compSize));
      else if (acc.componentType===5123) v.push(bin.readUInt16LE(o+c*compSize));
      else if (acc.componentType===5125) v.push(bin.readUInt32LE(o+c*compSize));
    }
    out.push(v);
  }
  return out;
}
const m = gltf.meshes[1]; // Bloc de chauffe
const p = m.primitives[0];
const pos = getAccessor(p.attributes.POSITION);
const idx = getAccessor(p.indices).map(v=>v[0]);
console.log('triangles', idx.length/3);
// find bottom face verts (y near min = 1.125)
const minY = Math.min(...pos.map(v=>v[1]));
const bottomVerts = pos.map((v,i)=>({i,v})).filter(o=>Math.abs(o.v[1]-minY)<0.01);
console.log('bottom verts count', bottomVerts.length);
console.log(bottomVerts.map(o=>o.v.map(x=>x.toFixed(3))));
// count triangles fully on bottom plane
let bottomTris=0;
const bottomSet = new Set(bottomVerts.map(o=>o.i));
for (let t=0;t<idx.length;t+=3){
  if (bottomSet.has(idx[t])&&bottomSet.has(idx[t+1])&&bottomSet.has(idx[t+2])) bottomTris++;
}
console.log('bottom-only triangles', bottomTris);
"

