// dédié — jamais bodyMat, translucide (alpha 0.55) et donc impropre à boucher quoi que ce soit —
// ni soumis lui-même au plan de coupe (sinon il disparaîtrait avec le reste).
const headCapMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadCapMat`, scene);
