1	import { useEffect, useRef, useState } from 'react';
2	import { showError, showSuccess, showWarning } from '@/utils/toast';
3	import {
4	  parseGCode,
5	  stateAt,
6	  timeAtIndex,
7	  indexAtTime,
8	  SUSPICIOUS_C_RANGE_DEG,
9	  type ParsedGCode,
10	} from '@/components/gcodeLayer';
11	
12	/**
13	 * Logique de l'espace Prévisualisation, sans interface : chargement de fichier G-code (dépôt sur
14	 * la fenêtre ou sélecteur), horloge de lecture et affichage des trajets à vide. Le rendu 3D est
15	 * fait par Viewport3D, piloté par les événements :
16	 *  - `apex-gcode-loaded` { parsed } : nouvelle trajectoire à afficher ;
17	 *  - `apex-gcode-time` { t } : position de lecture (index de mouvement fractionnaire) ;
18	 *  - `apex-gcode-show-travel` { show } : affichage des trajets à vide.
19	 */
20	
21	// Multiplicateurs du temps machine réel (1 = vitesse d'impression réelle, avances F du fichier).
22	export const GCODE_SPEED_OPTIONS = [0.01, 1, 4, 16, 64, 256];
23	export const GCODE_ACCEPT = '.gcode,.gco,.g,.ngc';
24	const ACCEPTED_EXT = /\.(gcode|gco|g|ngc)$/i;
25	
26	export interface GCodeFileInfo {
27	  name: string;
28	  moves: number;
29	  extruding: number;
30	  minZ: number;
31	  maxZ: number;
32	  minC: number;
33	  maxC: number;
34	}
