36	const dispatchTime = (t: number) =>
37	  window.dispatchEvent(new CustomEvent('apex-gcode-time', { detail: { t } }));
38	
39	/** @param active Espace Prévisualisation affiché (active le dépôt de fichier, coupe la lecture sinon). */
40	export function useGCodePreview(active: boolean) {
41	  const parsedRef = useRef<ParsedGCode | null>(null);
42	  const tRef = useRef(0);
43	  const dragDepthRef = useRef(0);
44	
45	  const [fileInfo, setFileInfo] = useState<GCodeFileInfo | null>(null);
46	  const [t, setT] = useState(0);
47	  const [isPlaying, setIsPlaying] = useState(false);
48	  const [speed, setSpeed] = useState(GCODE_SPEED_OPTIONS[1]);
49	  const [showTravel, setShowTravel] = useState(false);
50	  const [showFullHead, setShowFullHead] = useState(true);
51	  const [isDragging, setIsDragging] = useState(false);
52	  // Le temps de lire le fichier et de parser son texte (`loadFile`, ci-dessous) : permet à
53	  // GCodePreviewBar de s'afficher dès le début du chargement plutôt que d'attendre `fileInfo`.
54	  const [isLoading, setIsLoading] = useState(false);
55	
56	  useEffect(() => {
57	    if (!active) setIsPlaying(false);
58	  }, [active]);
59	
60	  useEffect(() => {
61	    window.dispatchEvent(new CustomEvent('apex-gcode-show-travel', { detail: { show: showTravel } }));
62	  }, [showTravel]);
63	
64	  useEffect(() => {
65	    window.dispatchEvent(new CustomEvent('apex-gcode-show-full-head', { detail: { show: showFullHead } }));
66	  }, [showFullHead]);
67	
68	  // Horloge de lecture : avance le temps machine (durées réelles des mouvements, cf.
69	  // `ParsedGCode.times`) à `speed` × le temps réel, le reconvertit en index de mouvement `t`,
70	  // pousse chaque image au viewport et rafraîchit l'état React à ~20 Hz seulement.
71	  useEffect(() => {
72	    if (!isPlaying) return;
73	    const parsed = parsedRef.current;
74	    if (!parsed) return;
75	    const last = parsed.moves.length - 1;
76	    let raf = 0;
77	    let prev = performance.now();
78	    let sinceUiSync = 0;
79	    const step = (now: number) => {
80	      const dt = (now - prev) / 1000;
81	      prev = now;
82	      const s = timeAtIndex(parsed.times, tRef.current) + speed * dt;
83	      tRef.current = Math.min(last, indexAtTime(parsed.times, s));
84	      dispatchTime(tRef.current);
85	      sinceUiSync += dt;
86	      if (tRef.current >= last) {
87	        setT(last);
88	        setIsPlaying(false);
89	        return;
90	      }
91	      if (sinceUiSync > 1 / 20) {
92	        sinceUiSync = 0;
93	        setT(tRef.current);
94	      }
95	      raf = requestAnimationFrame(step);
96	    };
97	    raf = requestAnimationFrame(step);
98	    return () => cancelAnimationFrame(raf);
99	  }, [isPlaying, speed]);
100	
101	  const loadFile = async (file: File) => {
102	    if (!ACCEPTED_EXT.test(file.name)) {
103	      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
104	      return;
105	    }
106	    setIsLoading(true);
107	    let parsed: ParsedGCode;
108	    try {
109	      parsed = parseGCode(await file.text());
110	    } catch {
111	      showError('Impossible de lire ce fichier G-code.');
112	      setIsLoading(false);
113	      return;
114	    }
115	    if (parsed.moves.length < 2) {
116	      showError('Aucune trajectoire G00 exploitable dans ce fichier.');
117	      setIsLoading(false);
118	      return;
119	    }
120	
121	    parsedRef.current = parsed;
122	    const last = parsed.moves.length - 1;
123	    tRef.current = last;
124	    setIsPlaying(false);
125	    setT(last);
126	    window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));
127	
128	    setFileInfo({
129	      name: file.name,
130	      moves: parsed.moves.length,
131	      extruding: parsed.extrudingCount,
132	      minZ: parsed.minZ,
133	      maxZ: parsed.maxZ,
134	      minC: parsed.minC,
135	      maxC: parsed.maxC,
136	    });
137	    setIsLoading(false);
138	
139	    if (parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
140	      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
141	    } else {
142	      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
143	    }
144	  };
145	
146	  /** Ouvre le sélecteur de fichier système (sans élément `<input>` dans l'interface). */
147	  const openFilePicker = () => {
148	    const input = document.createElement('input');
149	    input.type = 'file';
150	    input.accept = GCODE_ACCEPT;
151	    input.onchange = () => {
152	      const file = input.files?.[0];
153	      if (file) loadFile(file);
154	    };
155	    input.click();
156	  };
157	
158	  // Dépôt de fichier sur toute la fenêtre tant que l'espace est affiché : le viewport garde la
159	  // souris pour la caméra, aucun élément d'interface n'a donc besoin de capter le dépôt.
160	  useEffect(() => {
161	    if (!active) return;
162	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
163	    const onDragEnter = (e: DragEvent) => {
164	      if (!hasFiles(e)) return;
165	      e.preventDefault();
166	      dragDepthRef.current++;
167	      setIsDragging(true);
168	    };
169	    const onDragOver = (e: DragEvent) => {
170	      if (!hasFiles(e)) return;
171	      e.preventDefault();
172	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
173	    };
174	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
175	    const onDragLeave = (e: DragEvent) => {
176	      if (!hasFiles(e)) return;
177	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
178	      if (dragDepthRef.current === 0) setIsDragging(false);
179	    };
180	    const onDrop = (e: DragEvent) => {
181	      if (!hasFiles(e)) return;
182	      e.preventDefault();
183	      dragDepthRef.current = 0;
184	      setIsDragging(false);
185	      const file = e.dataTransfer?.files?.[0];
186	      if (file) loadFile(file);
187	    };
188	    window.addEventListener('dragenter', onDragEnter);
189	    window.addEventListener('dragover', onDragOver);
190	    window.addEventListener('dragleave', onDragLeave);
191	    window.addEventListener('drop', onDrop);
192	    return () => {
193	      window.removeEventListener('dragenter', onDragEnter);
194	      window.removeEventListener('dragover', onDragOver);
195	      window.removeEventListener('dragleave', onDragLeave);
196	      window.removeEventListener('drop', onDrop);
197	      dragDepthRef.current = 0;
198	      setIsDragging(false);
199	    };
200	  }, [active]);
201	
202	  /** Place la lecture sur l'index de mouvement `value` (fractionnaire) et met la lecture en pause. */
203	  const seek = (value: number) => {
204	    setIsPlaying(false);
205	    tRef.current = value;
206	    setT(value);
207	    dispatchTime(value);
208	  };
209	
210	  /** Lecture/pause ; repart du début si la lecture est au bout. */
211	  const togglePlay = () => {
212	    const parsed = parsedRef.current;
213	    if (!parsed) return;
214	    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
215	    setIsPlaying(!isPlaying);
216	  };
217	
218	  const parsed = parsedRef.current;
219	  /** État machine interpolé (r, c, z, b) à la position de lecture. */
220	  const current = parsed ? stateAt(parsed.moves, t) : null;
221	  /** Mouvement en cours d'exécution (pour savoir s'il extrude). */
222	  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
223	  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;
224	
225	  return {
226	    fileInfo,
227	    t,
228	    lastIndex,
229	    current,
230	    currentMove,
231	    isPlaying,
232	    togglePlay,
233	    seek,
234	    speed,
235	    setSpeed,
236	    showTravel,
237	    setShowTravel,
238	    showFullHead,
239	    setShowFullHead,
240	    isDragging,
241	    isLoading,
242	    loadFile,
243	    openFilePicker,
244	  };
245	}
