const nozzleMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}NozzleMat`, scene);
nozzleMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
nozzle.position.y = 4.5;
nozzle.material = nozzleMat;
nozzle.parent = headNode;
const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
bodyMat.alpha = 0.55;
const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
body.position.y = 9 + 13;
body.material = bodyMat;
body.parent = headNode;
nozzle.isPickable = false;
body.isPickable = false;
headNode.setEnabled(false);
registerHeadMaterial(nozzleMat);
registerHeadMaterial(bodyMat);

// Bouchon des primitives de repli SEULEMENT (rayon = celui de `body`) : `CreateCylinder` les
// ferme déjà à leurs deux extrémités, mais pas à la hauteur de coupe, bien plus bas — sans ce
// disque, la troncature les laisserait creuses. Inutile une fois le modèle glTF chargé (cf. son
// `.then` ci-dessous, qui le dispose) : le vrai modèle, lui, est coupé exactement à la face
// inférieure DÉJÀ FERMÉE du « Bloc de chauffe » (cf. HEAD_CLIP_HEIGHT_MM), bonne forme et bon
// matériau sans bouchon générique. Face tournée vers le bas (rotation X, une CreateDisc étant
// nativement tournée vers +Y) puisque c'est de là qu'elle sera vue. Matériau opaque dédié —
// jamais bodyMat, translucide (alpha 0.55) — ni soumis lui-même au plan de coupe.
const headCapMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadCapMat`, scene);
headCapMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
const headCap = BABYLON.MeshBuilder.CreateDisc(`${GCODE_MESH_PREFIX}HeadCap`, { radius: 7, tessellation: 24 }, scene);
headCap.rotation.x = Math.PI / 2;
headCap.position.y = HEAD_CLIP_HEIGHT_MM;
headCap.material = headCapMat;
headCap.parent = headNode;
headCap.isPickable = false;
headCap.setEnabled(!fullHead);

