464	}
465	
466	export interface GCodeLayer {
467	  load(parsed: ParsedGCode): void;
468	  /** Position de lecture, en index de mouvement fractionnaire. */
469	  setTime(t: number): void;
470	  setShowTravel(show: boolean): void;
471	  /** Tête complète (défaut) ou tronquée à HEAD_CLIP_HEIGHT_MM au-dessus de la pointe de buse, pour
472	   * ne laisser voir que la buse elle-même (cf. `apex-gcode-show-full-head`). */
473	  setFullHead(show: boolean): void;
474	  setEnabled(enabled: boolean): void;
475	  /** Rotation courante du plateau autour de Y (radians, repère Babylon), 0 sans G-code. */
476	  getPlateRotation(): number;
477	  dispose(): void;
478	}
479	
480	/** Préfixe de nom de tous les maillages du calque (cf. exclusion de la capture du flou). */
481	export const GCODE_MESH_PREFIX = 'gcode';
482	
483	/** Le glTF est en mètres, la scène en millimètres. */
484	const GLTF_TO_MM = 1000;
485	/** Rotation du modèle de tête autour de l'axe de sa buse (radians) : tel qu'exporté, son axe de
486	 * basculement B est perpendiculaire à celui de la machine (Z du repère tête, la tête penchant
487	 * dans le plan radial XY). */
488	const HEAD_MODEL_YAW = Math.PI / 2;
489	
490	/** Hauteur de troncature de la tête (mm) au-dessus de la pointe de buse (origine de `headNode`),
491	 * quand « Afficher la tête d'outil complète » est décoché (cf. `setFullHead`). Calée EXACTEMENT
492	 * sur la face inférieure, déjà fermée, du maillage « Bloc de chauffe » du modèle (aetheris-4.glb :
493	 * hexagone chanfreiné à Y = 1.125 dans son repère d'origine, × 10 après mise à l'échelle du
494	 * noeud) : la coupe expose ainsi cette face réelle (bonne forme, bon matériau) plutôt qu'un
495	 * bouchon générique qui ne correspondrait ni à l'une ni à l'autre. Un epsilon la fait déborder
496	 * légèrement DANS le bloc de chauffe plutôt que de s'arrêter pile sur son plan, ce qui laisserait
497	 * sa propre face au bord du clip disparaître par endroits selon l'arrondi flottant. */
498	const HEAD_CLIP_HEIGHT_MM = 11.25 + 0.05;
499	
500	/**
501	 * Charge le modèle de la tête (aetheris-4.glb) sous `headNode`, pointe de buse à l'origine du
502	 * noeud et corps vers +Y local. Le fichier est déjà posé debout sur la buse, mais le centre de
503	 * la face de sortie de la buse (maillage « NOZZLE origin ») est légèrement décalé de son
504	 * origine : on recale le modèle sur ce point plutôt que de faire confiance à l'origine.
505	 * Chargé dans un conteneur et renommé AVANT l'ajout à la scène : Viewport3D trie les maillages
506	 * par nom dès leur arrivée (capture du flou, sélection de modèles) et doit ignorer ceux du calque.
507	 */
508	async function loadHeadModel(scene: BABYLON.Scene, headNode: BABYLON.TransformNode, isDisposed: () => boolean) {
509	  const container = await BABYLON.SceneLoader.LoadAssetContainerAsync('', headModelUrl, scene, null, '.glb');
510	  if (isDisposed()) {
511	    container.dispose();
512	    return false;
513	  }
514	  const prefix = `${GCODE_MESH_PREFIX}HeadModel_`;
515	  for (const mesh of container.meshes) {
516	    mesh.name = prefix + mesh.name;
517	    mesh.isPickable = false;
518	  }
519	  for (const node of container.transformNodes) node.name = prefix + node.name;
520	
521	  const model = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}HeadModel`, scene);
522	  model.scaling.setAll(GLTF_TO_MM);
523	  for (const node of container.rootNodes) node.parent = model;
524	
525	  // Pointe de buse mesurée avec le modèle seul (non encore rattaché à la tête) : son repère
526	  // monde n'est alors que l'échelle, donc la boîte monde est directement en repère tête.
527	  const nozzle = container.meshes.find((m) => m.name.includes('NOZZLE origin'));
528	  if (nozzle) {
529	    const chain: BABYLON.Node[] = [];
530	    for (let n: BABYLON.Node | null = nozzle; n; n = n.parent) chain.unshift(n);
531	    for (const n of chain) (n as BABYLON.TransformNode).computeWorldMatrix(true);
532	    const { minimumWorld: min, maximumWorld: max } = nozzle.getBoundingInfo().boundingBox;
533	    model.position.set(-(min.x + max.x) / 2, -min.y, -(min.z + max.z) / 2);
534	  }
535	  // Rotation portée par un noeud intermédiaire, APRÈS le recalage : elle tourne autour de l'axe
536	  // vertical passant par la pointe de buse, qui reste donc à l'origine.
537	  const mount = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}HeadModelMount`, scene);
538	  mount.rotation.y = HEAD_MODEL_YAW;
539	  mount.parent = headNode;
540	  model.parent = mount;
541	  container.addAllToScene();
542	  return true;
543	}
544	
545	/**
546	 * Calque de prévisualisation G-code posé dans une scène existante. `parent` est le repère du
547	 * plateau (origine au centre de sa surface) : Z = 0 du G-code y correspond.
548	 */
549	export function createGCodeLayer(
550	  scene: BABYLON.Scene,
551	  parent: BABYLON.TransformNode,
552	  /** Appelé à chaque mise à jour de la rotation du plateau (radians), pour y caler du décor. */
553	  onPlateRotation?: (rotationY: number) => void,
554	): GCodeLayer {
555	  const root = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Root`, scene);
556	  root.parent = parent;
557	  root.setEnabled(false);
558	
559	  // Repère tournant du plateau : toute la matière déposée en est enfant.
560	  const plateNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Plate`, scene);
561	  plateNode.parent = root;
562	
563	  // Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le noeud
564	  // est ensuite orienté pour que ce corps penche de B vers +R. Primitives provisoires, remplacées
565	  // par le vrai modèle (loadHeadModel) une fois chargé ; gardées en repli s'il échoue.
566	  const headNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Head`, scene);
567	  headNode.parent = root;
568	  headNode.rotationQuaternion = BABYLON.Quaternion.Identity();
569	
570	  // Troncature de la tête : un plan de coupe (repère MONDE, cf. Material.clipPlane) posé à
571	  // HEAD_CLIP_HEIGHT_MM au-dessus de la pointe de buse, normale vers le bas — tout ce qui est
572	  // au-dessus disparaît, ne laissant voir que la buse. Recalculé à chaque `apply()` puisque
573	  // `headNode` bouge et s'incline avec la position/B courants. Un seul plan, partagé par tous les
574	  // matériaux de la tête (primitives de repli + modèle glTF, potentiellement plusieurs matériaux) :
575	  // `material.clipPlane` prend l'objet lui-même, jamais recréé, pour éviter une allocation par frame.
576	  const headClipPlane = new BABYLON.Plane(0, -1, 0, 0);
577	  const headClipMaterials = new Set<BABYLON.Material>();
578	  let fullHead = true;
579	  const registerHeadMaterial = (mat: BABYLON.Material | null | undefined) => {
580	    if (!mat || headClipMaterials.has(mat)) return;
581	    headClipMaterials.add(mat);
582	    mat.clipPlane = fullHead ? null : headClipPlane;
583	  };
584	
585	  const nozzleMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}NozzleMat`, scene);
586	  nozzleMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
587	  nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
588	  const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
589	  nozzle.position.y = 4.5;
590	  nozzle.material = nozzleMat;
591	  nozzle.parent = headNode;
592	  const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
593	  bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
594	  bodyMat.alpha = 0.55;
595	  const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
596	  body.position.y = 9 + 13;
597	  body.material = bodyMat;
598	  body.parent = headNode;
599	  nozzle.isPickable = false;
600	  body.isPickable = false;
601	  headNode.setEnabled(false);
602	  registerHeadMaterial(nozzleMat);
603	  registerHeadMaterial(bodyMat);
604	
605	  // Bouchon des primitives de repli SEULEMENT : `CreateCylinder` les ferme déjà à leurs deux
606	  // extrémités, mais pas à la hauteur de coupe, qui tombe entre les deux (au-dessus du sommet du
607	  // cône `nozzle`, en dessous de la base de `body`) — sans ce disque, la troncature laisserait un
608	  // vide à cet endroit plutôt qu'une coquille creuse. Rayon = celui du SOMMET du cône de la buse
609	  // (diameterTop / 2), pas celui, bien plus large, de `body` : la coupe continue visuellement la
610	  // buse qui rétrécit vers sa pointe, jamais un plateau élargi à la taille du corps au-dessus.
611	  // Inutile une fois le modèle glTF chargé (cf. son `.then` ci-dessous, qui le dispose) : le vrai
612	  // modèle, lui, est coupé exactement à la face inférieure DÉJÀ FERMÉE du « Bloc de chauffe » (cf.
613	  // HEAD_CLIP_HEIGHT_MM), bonne forme et bon matériau sans bouchon générique. Face tournée vers le
614	  // bas (rotation X, une CreateDisc étant nativement tournée vers +Y) puisque c'est de là qu'elle
615	  // sera vue. Même matériau que `nozzle`, dont cette face de coupe prolonge la surface — jamais
