  // HEAD_CLIP_HEIGHT_MM au-dessus de la pointe de buse, normale vers le bas — tout ce qui est
  // au-dessus disparaît, ne laissant voir que la buse. Recalculé à chaque `apply()` puisque
  // `headNode` bouge et s'incline avec la position/B courants. Un seul plan, partagé par tous les
  // matériaux de la tête (primitives de repli + modèle glTF, potentiellement plusieurs matériaux) :
  // `material.clipPlane` prend l'objet lui-même, jamais recréé, pour éviter une allocation par frame.
  const headClipPlane = new BABYLON.Plane(0, -1, 0, 0);
  const headClipMaterials = new Set<BABYLON.Material>();
