  // Disposé dès que le vrai modèle a chargé sa propre face de coupe (cf. plus haut) : n'existe
  // donc plus forcément à cet instant.
  if (!headCap.isDisposed()) headCap.setEnabled(!show);
  if (show) {
    for (const mat of headClipMaterials) mat.clipPlane = null;
  } else {
    updateHeadClipPlane();
    for (const mat of headClipMaterials) mat.clipPlane = headClipPlane;
  }
},
setEnabled(enabled) {
  root.setEnabled(enabled);
},
getPlateRotation() {
  return plateNode.rotation.y;
},

