file.content:
nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
nozzle.position.y = 4.5;
nozzle.material = nozzleMat;
nozzle.parent = headNode;
const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
bodyMat.alpha = 0.55;
const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
body.position.y = 9 + 13;
body.material = bodyMat;
body.parent = headNode;
nozzle.isPickable = false;
body.isPickable = false;
headNode.setEnabled(false);
registerHeadMaterial(nozzleMat);
registerHeadMaterial(bodyMat);

// Bouchon des primitives de repli SEULEMENT : `CreateCylinder` les ferme déjà à leurs deux
// extrémités, mais pas à la hauteur de coupe, qui tombe entre les deux (au-dessus du sommet du
// cône `nozzle`, en dessous de la base de `body`) — sans ce disque, la troncature laisserait un
// vide à cet endroit plutôt qu'une coquille creuse. Rayon = celui du SOMMET du cône de la buse
// (diameterTop / 2), pas celui, bien plus large, de `body` : la coupe continue visuellement la
// buse qui rétrécit vers sa pointe, jamais un plateau élargi à la taille du corps au-dessus.
// Inutile une fois le modèle glTF chargé (cf. son `.then` ci-dessous, qui le dispose) : le vrai
// modèle, lui, est coupé exactement à la face inférieure DÉJÀ FERMÉE du « Bloc de chauffe » (cf.
// HEAD_CLIP_HEIGHT_MM), bonne forme et bon matériau sans bouchon générique. Face tournée vers le
// bas (rotation X, une CreateDisc étant nativement tournée vers +Y) puisque c'est de là qu'elle
// sera vue. Même matériau que `nozzle`, dont cette face de coupe prolonge la surface — jamais
// bodyMat (gris, translucide, celui du corps bien plus large au-dessus) — ni soumis lui-même au
// plan de coupe.
const headCap = BABYLON.MeshBuilder.CreateDisc(`${GCODE_MESH_PREFIX}HeadCap`, { radius: 3.5, tessellation: 20 }, scene);
headCap.rotation.x = Math.PI / 2;
headCap.position.y = HEAD_CLIP_HEIGHT_MM;
headCap.material = nozzleMat;
headCap.parent = headNode;
headCap.isPickable = false;
headCap.setEnabled(!fullHead);

let disposed = false;
loadHeadModel(scene, headNode, () => disposed)
  .then((loaded) => {
    if (!loaded) return;
    nozzle.dispose(false, true);
    body.dispose(false, true);
    // Le vrai modèle a sa propre face de coupe déjà fermée (cf. HEAD_CLIP_HEIGHT_MM) : ce disque
    // générique, qui n'allait qu'aux primitives, n'a plus lieu d'être et flotterait sinon près
    // de la vraie face du bloc de chauffe.
    headCap.dispose(false, true);
    // Modèle glTF : potentiellement plusieurs matériaux (un par sous-maillage), tous soumis au
    // même plan de coupe que les primitives qu'ils remplacent.
    for (const mesh of headNode.getChildMeshes()) registerHeadMaterial(mesh.material);
  })
  .catch((err) => console.warn('Modèle de tête G-code non chargé, primitives conservées :', err));

// Cordon : teinte portée par les couleurs de sommets (dégradé en hauteur), le matériau n'apporte
// que l'éclairage. Faces arrière dessinées pour ne pas dépendre du sens des triangles, les
// normales explicites (vers l'extérieur) donnant l'éclairage.
const beadMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}BeadMat`, scene);
beadMat.diffuseColor = new BABYLON.Color3(1, 1, 1);
beadMat.specularColor = new BABYLON.Color3(0.25, 0.25, 0.25);
beadMat.specularPower = 48;
beadMat.emissiveColor = new BABYLON.Color3(0.08, 0.1, 0.14);
beadMat.backFaceCulling = false;

