    for (const mesh of headNode.getChildMeshes()) {
      if (!mesh.name.includes('NOZZLE')) mesh.setEnabled(fullHead);
    }
  })
  .catch((err) => console.warn('Modèle de tête G-code non chargé, primitives conservées :', err));

