file.content:
export interface GCodeLayer {
  load(parsed: ParsedGCode): void;
  /** Position de lecture, en index de mouvement fractionnaire. */
  setTime(t: number): void;
  setShowTravel(show: boolean): void;
  /** Tête complète (défaut) ou tronquée à HEAD_CLIP_HEIGHT_MM au-dessus de la pointe de buse, pour
   * ne laisser voir que la buse elle-même (cf. `apex-gcode-show-full-head`). */
  setFullHead(show: boolean): void;
  setEnabled(enabled: boolean): void;
  /** Rotation courante du plateau autour de Y (radians, repère Babylon), 0 sans G-code. */
  getPlateRotation(): number;
  dispose(): void;
}

/** Préfixe de nom de tous les maillages du calque (cf. exclusion de la capture du flou). */
export const GCODE_MESH_PREFIX = 'gcode';

/** Le glTF est en mètres, la scène en millimètres. */
const GLTF_TO_MM = 1000;
/** Rotation du modèle de tête autour de l'axe de sa buse (radians) : tel qu'exporté, son axe de
 * basculement B est perpendiculaire à celui de la machine (Z du repère tête, la tête penchant
 * dans le plan radial XY). */
const HEAD_MODEL_YAW = Math.PI / 2;

/** Hauteur de troncature de la tête (mm) au-dessus de la pointe de buse (origine de `headNode`),
 * quand « Afficher la tête d'outil complète » est décoché (cf. `setFullHead`). Calée EXACTEMENT
 * sur la face inférieure, déjà fermée, du maillage « Bloc de chauffe » du modèle (aetheris-4.glb :
 * hexagone chanfreiné à Y = 1.125 dans son repère d'origine, × 10 après mise à l'échelle du
 * noeud) : la coupe expose ainsi cette face réelle (bonne forme, bon matériau) plutôt qu'un
 * bouchon générique qui ne correspondrait ni à l'une ni à l'autre. Un epsilon la fait déborder
 * légèrement DANS le bloc de chauffe plutôt que de s'arrêter pile sur son plan, ce qui laisserait
 * sa propre face au bord du clip disparaître par endroits selon l'arrondi flottant. */
const HEAD_CLIP_HEIGHT_MM = 11.25 + 0.05;

